export function eval_rpn(expr: string): number {
  const tokens = expr.split(" ").filter((t) => t !== "");
  const stack: number[] = [];
  for (const tok of tokens) {
    if (/^-?\d+$/.test(tok)) {
      stack.push(Number(tok));
      continue;
    }
    if (tok === "+" || tok === "-" || tok === "*" || tok === "/") {
      if (stack.length < 2) throw new Error("stack underflow");
      const b = stack.pop() as number;
      const a = stack.pop() as number;
      let r: number;
      if (tok === "+") r = a + b;
      else if (tok === "-") r = a - b;
      else if (tok === "*") r = a * b;
      else {
        if (b === 0) throw new Error("division by zero");
        r = Math.trunc(a / b) || 0;
      }
      stack.push(r);
      continue;
    }
    throw new Error(`bad token ${tok}`);
  }
  if (stack.length !== 1) throw new Error("bad expression");
  return stack[0];
}
